// Package uninstall implements the signed uninstall ticket.
//
// Removing an agent is deliberately not a local decision: the operator starts an
// uninstall on the host, the control plane records a request, an administrator
// approves it, and only then does the control plane sign a short-lived ticket
// bound to the node, the request and the client's nonce. The agent verifies the
// ticket with the policy public key before touching anything. The same ticket can
// also be generated by an administrator directly ("uninstall from the management
// plane"), which is the second and only other path.
package uninstall

import (
	"bytes"
	"crypto/ed25519"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"time"
)

// ActionUninstall is the only action a ticket may carry.
const ActionUninstall = "uninstall"

const ticketVersion = "tg-uninstall-ticket-v1"

// Status values of an uninstall request.
const (
	StatusPending  = "pending"
	StatusApproved = "approved"
	StatusDenied   = "denied"
	StatusDone     = "done"
)

// Options describes what an uninstall removes.
type Options struct {
	StateDir    string
	BinaryPath  string
	UnitPath    string
	ServiceName string
	DryRun      bool
}

// Ticket authorises one uninstall of one node.
type Ticket struct {
	Version   int    `json:"version"`
	NodeID    string `json:"node_id"`
	RequestID string `json:"request_id"`
	Nonce     string `json:"nonce"`
	Action    string `json:"action"`
	IssuedAt  int64  `json:"issued_at"`
	ExpiresAt int64  `json:"expires_at"`
	Signature string `json:"signature"`
}

// Canonical returns the signed byte string.
func (t *Ticket) Canonical() []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s\nnode=%s\nrequest=%s\nnonce=%s\naction=%s\nissued_at=%d\nexpires_at=%d\n",
		ticketVersion, t.NodeID, t.RequestID, t.Nonce, t.Action, t.IssuedAt, t.ExpiresAt)
	return b.Bytes()
}

// Sign fills the signature (and IssuedAt/ExpiresAt when unset).
func Sign(priv ed25519.PrivateKey, t *Ticket) error {
	if len(priv) != ed25519.PrivateKeySize {
		return errors.New("uninstall: invalid signing key")
	}
	if t.NodeID == "" || t.RequestID == "" || t.Nonce == "" {
		return errors.New("uninstall: incomplete ticket")
	}
	if t.Action == "" {
		t.Action = ActionUninstall
	}
	now := time.Now().Unix()
	if t.IssuedAt == 0 {
		t.IssuedAt = now
	}
	if t.ExpiresAt == 0 {
		t.ExpiresAt = now + 600 // 10 minutes
	}
	t.Version = 1
	t.Signature = base64.StdEncoding.EncodeToString(ed25519.Sign(priv, t.Canonical()))
	return nil
}

// Verify checks the signature, action and expiry against now.
func Verify(pub ed25519.PublicKey, t *Ticket, now time.Time) error {
	if len(pub) != ed25519.PublicKeySize {
		return errors.New("uninstall: invalid public key")
	}
	if t.Signature == "" {
		return errors.New("uninstall: ticket is not signed")
	}
	if t.Action != ActionUninstall {
		return fmt.Errorf("uninstall: unexpected action %q", t.Action)
	}
	if t.ExpiresAt == 0 || now.Unix() > t.ExpiresAt {
		return errors.New("uninstall: ticket expired")
	}
	sig, err := base64.StdEncoding.DecodeString(t.Signature)
	if err != nil {
		return fmt.Errorf("uninstall: signature encoding: %w", err)
	}
	if !ed25519.Verify(pub, t.Canonical(), sig) {
		return errors.New("uninstall: ticket signature does not verify")
	}
	return nil
}

// EncodeTicket serialises a ticket for transport in an SSE payload or for the
// operator to paste into `tg-agent uninstall --ticket`.
func EncodeTicket(t *Ticket) (string, error) {
	raw, err := json.Marshal(t)
	if err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(raw), nil
}

// DecodeTicket parses a ticket produced by EncodeTicket.
func DecodeTicket(s string) (*Ticket, error) {
	raw, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return nil, err
	}
	var t Ticket
	if err := json.Unmarshal(raw, &t); err != nil {
		return nil, err
	}
	return &t, nil
}

// Nonce returns a fresh random nonce for a request/ticket pair.
func Nonce() (string, error) {
	buf := make([]byte, 24)
	if _, err := rand.Read(buf); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(buf), nil
}
